package com.smartmart.discount.controller; import com.smartmart.discount.dto.DiscountRequest; import com.smartmart.inventory.dto.InventoryResponse; import com.smartmart.inventory.service.InventoryService; import jakarta.validation.Valid; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/discounts") @RequiredArgsConstructor public class DiscountController{private final InventoryService inventory; @GetMapping public List<InventoryResponse> active(){return inventory.discounted();}@PutMapping("/product/{productId}") @PreAuthorize("hasRole('MANAGER')") public InventoryResponse apply(@PathVariable Long productId,@Valid @RequestBody DiscountRequest r){InventoryResponse current=inventory.product(productId);com.smartmart.inventory.dto.InventoryRequest req=new com.smartmart.inventory.dto.InventoryRequest();req.setProductId(current.getProductId());req.setQuantity(current.getQuantity());req.setReorderLevel(current.getReorderLevel());req.setExpiryDate(current.getExpiryDate());req.setDiscountPercentage(r.getPercentage());return inventory.update(current.getId(),req);}}
